CREATE DATABASE IF NOT EXISTS nexora_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexora_db;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS clients(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,company VARCHAR(160),email VARCHAR(190) NOT NULL,phone VARCHAR(40),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(name),INDEX(email)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id INT UNSIGNED NULL,name VARCHAR(180) NOT NULL,description TEXT,status ENUM('Planning','In Progress','On Hold','Completed','Cancelled') NOT NULL DEFAULT 'Planning',budget DECIMAL(12,2),start_date DATE,end_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),CONSTRAINT fk_projects_client FOREIGN KEY(client_id) REFERENCES clients(id) ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inquiries(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),subject VARCHAR(180),message TEXT,status ENUM('New','Contacted','Resolved') NOT NULL DEFAULT 'New',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),INDEX(created_at)) ENGINE=InnoDB;
